 window.addEventListener('click',async e=>{const b=e.target.closest?.('[data-vault-choose],[data-vault-open],[data-vault-clear],[data-vault-sync],[data-server-disconnect]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(busy)return;try{await flushPersonalDrafts();await persistGlassSettings();setBusy(true);if(b.hasAttribute('data-vault-choose')){const r=await invoke('chooseStorage');if(r?.restarting)setTaskStatus('资料迁移完成，正在重启…',true)}else if(b.hasAttribute('data-vault-open'))await invoke('openStorage');else if(b.hasAttribute('data-vault-clear')){const r=await invoke('clearPersonalLibrary');if(r){state.library=r.library;selection.clear();selectionMode=false;catalogClient.details.clear();updateNavigation();YingjiWorkspace.clearPersonalMemory();thumbnailCache.clear();catalogClient.byId.clear();catalogClient.items=[];catalogClient.requestId++;Object.assign(state,{query:'',category:'all',year:'all',status:'all',materialFilter:'all'});undoDeletion=null;toast('资料库与素材副本已清空，电脑源文件保留')}}else if(b.hasAttribute('data-server-disconnect')){await invoke('disconnectServer');await readStorage();toast('服务器连接已移除')}else{const result=await invoke('serverSync',{direction:b.dataset.vaultSync});if(result){if(result.library){state.library=result.library;catalogClient.details.clear();thumbnailCache.clear();updateNavigation()}await readStorage();toast('服务器同步完成')}}}catch(error){toast(error.message);setTaskStatus('操作未完成：'+error.message)}finally{setBusy(false)}},true);
